import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { GenericResult } from 'src/app/models/generic-result.model';
import { SecurityUtilsService } from 'src/app/services/security/security-utils.service';
import { LoginService } from 'src/app/services/signup/login.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  
  public form: FormGroup;

  constructor(
    private loginService: LoginService,
    private fb: FormBuilder,
    private router: Router,
    private securityService: SecurityUtilsService)
  {
    this.form = this.fb.group({
      password: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(50),
          Validators.required
        ])
      ],
      email: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(150),
          Validators.required
        ])
      ],
    })
  }

  login(rowdata: any){
    // this.service.login(this.form.value).subscribe( (data: any) => {
    //   this.router.navigate(['/home']); // todo refatorar
    // },
    // (err) => {
    //   console.log(err);
    // })
    this.loginService.login(this.form.value)
    .subscribe( 
      {
      next: (result: GenericResult) => {
        console.log('login ', result)
        if(result.success == true){
          this.securityService.grantedAuthorization(result.data);
          this.router.navigate(['/login']);
        }
        else {
          console.log('login com problemas');
        }
      },
      error: (err) => {
        console.log(err)
      }
    });
  }
}
<div class="uk-flex-center" uk-grid>
  <div class="uk-width-1-3@m">
    <p class="uk-text-center uk-margin-large-top uk-margin-medium-bottom">
      <span>
        <img src="assets/images/ifood-43.png" style="width: 10%; height: 10%;">
      </span>
    </p>
    <form>
      <div class="uk-card uk-card-primary uk-card-body uk-box-shadow-small" id="login-color">
        <h3 class="uk-card-title">Autentique-se</h3>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="email" type="email" placeholder="Email">
        </div>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="password" type="password" placeholder="Senha">
        </div>

        <div class="uk-margin uk-text-right">
          <button class="uk-button uk-button-default" [routerLink]="['/home']" id="button-sign-in">Entrar</button>
        </div>

      </div>
    </form>

    <p class="uk-text-center">
      <a class="uk-button uk-width-1-1 uk-button-large uk-button-primary uk-margin-small-bottom" [routerLink]="['/signup']" id="login-color">Cadastrar</a>
      <br>
      <a class="uk-button uk-button-link" [routerLink]="['/resetpassword']">Esqueci minha senha</a>
    </p>

  </div>
</div>
